    summary: "西蒙的有限理性指出人的理性是有边界的，但并未系统阐明这些边界具体如何扭曲判断。卡尼曼与特沃斯基（1974, 1979）通过大量心理学实验揭示了一个更为惊人的事实：人类的判断偏误不是随机的，而是系统性的、可预测的——人们在不确定条件下大量依赖启发式（捷思法）做判断，由此产生锚定效应、可得性偏误、代表性偏误等稳定的认知偏差。前景理论进一步推翻了期望效用理论的核心假设：人在面对收益时规避风险，面对损失时追求风险，且损失带来的痛苦大于等量收益的快乐。塞勒将这些洞见延伸到经济行为和公共政策领域，提出「助推」概念——利用认知偏误来引导更优决策。这一研究传统从根本上动摇了主流经济学和管理学的理性人假设，卡尼曼和塞勒分获2002年和2017年诺贝尔经济学奖。",
