  harvard: {
    accent: "#007AFF", badge: "院校学派 · 美国",
    group: 12,
    title: "哈佛学派", en: "Harvard Business School (HBS)", ja: "ハーバード学派",
    era: "1908年创立 · 持续至今",
    who: ["迈克尔·波特 Michael Porter（竞争战略）", "约翰·科特 John Kotter（变革领导力）", "克莱顿·克里斯坦森 Clayton Christensen（颠覆性创新）", "罗莎贝斯·莫斯·坎特 Rosabeth Moss Kanter"],
    summary: "哈佛商学院（1908年创立）是现代管理学的核心发源地之一，其独特地位来自三重贡献：方法论上发明了案例教学法（Case Method），将管理学定位为「可在实践情境中教授的判断力」而非抽象理论；在竞争战略领域，波特的五力模型和价值链框架不仅奠定了战略管理学科的理论基础，更塑造了全球战略咨询行业的分析语言；在领导力和变革管理领域，科特的8步变革模型和克里斯坦森的颠覆性创新理论各自成为所在领域最有影响力的框架。HBS的学术风格深刻塑造了哈佛学派的特征：重视实践相关性胜于理论精致性，以大型成熟企业为主要研究对象，通过案例归纳而非演绎推理来构建理论。这一传统既是其影响力的来源也是其方法论局限——案例研究的事后归因偏差和样本局限性是持续争论的焦点。",
    concepts: ["k130", "k131", "k133"],
    influence: "战略咨询行业的理论基础，McKinsey等主要咨询公司的分析框架来源于此。案例教学法被全球商学院广泛采用。HBS案例库是全球最大的商业案例数据库。",
    context: "哈佛商学院1908年创立之初，美国企业界迫切需要能应对大规模公司管理挑战的专业人才，HBS在创立之初便确立了案例教学法，将管理定位为可教授的实践性学科。波特等人的战略研究主要兴起于1970-80年代应对美国企业竞争力下滑的现实背景。主要局限在于：哈佛学派研究以大型成熟企业为主要对象，对创业期企业和颠覆者的适用性有限；案例研究方法因样本局限和事后归因偏差受到方法论批评；波特框架的静态性在数字时代面临挑战。",
    related: ["产业组织学派", "战略规划学派", "创新管理学派", "敏捷 · 组织变革"]
  },

  chicago: {
    accent: "#007AFF", badge: "院校学派 · 美国",
    group: 12,
    title: "芝加哥学派", en: "University of Chicago (Booth School)", ja: "シカゴ学派",
    era: "20世纪初至今 · 经济学重镇",
    who: ["罗纳德·科斯 Ronald Coase", "米尔顿·弗里德曼 Milton Friedman", "尤金·法马 Eugene Fama", "乔治·斯蒂格勒 George Stigler"],
    summary: "芝加哥学派的思想传统建立在一个核心信念之上：自由市场中的价格机制是最有效的资源配置手段，政府干预通常弊大于利。弗里德曼的货币主义和自由市场理念为1980年代撒切尔-里根时代的全球市场化改革提供了知识基础。但芝加哥学派对管理学的最深远影响来自两个看似矛盾的方向：科斯（1937）追问了一个对价格理论而言极为尴尬的问题——如果市场如此高效，企业为什么存在？他的回答（市场交易有成本）开启了新制度经济学传统；法马的有效市场假说则将价格机制的效率信念推向极致，主张资本市场价格已经充分反映了所有可得信息。芝加哥学派的核心思想工具——理性自利的行为假设、产权明晰的制度设计、股东价值最大化的企业目标——在2008年金融危机后遭遇广泛反思，利益相关者理论的兴起标志着学界对其单一目标体系的系统性挑战。",
    concepts: ["k134", "k135", "k136", "k137"],
    influence: "1980年代撒切尔-里根时代的市场化改革提供了理论依据。股东价值最大化理念在2019年BRT声明后受到主流挑战，利益相关者理论兴起。",
    context: "芝加哥学派兴起于大萧条后自由市场理念受到强烈质疑的时代背景，弗里德曼等人以严格的价格理论为武器，重建了市场机制的经济学基础。其在管理学中的影响于1970-80年代随代理理论和资本市场研究的兴起而达到顶峰。主要局限在于：对市场效率的过度信仰导致低估了信息不对称、外部性和市场失灵的普遍性；股东价值最大化的单一目标体系在2008年金融危机后受到广泛反思；此外，将人类行为化约为理性自利的假设，忽视了社会规范、心理偏差和权力关系对经济行为的深刻影响。",
    related: ["交易成本理论", "代理理论", "CSR · 可持续管理（对立视角）"]
  },

