    who: ["伦西斯·李克特 Rensis Likert", "丹尼尔·卡茨 Daniel Katz", "罗伯特·卡恩 Robert Kahn"],
    summary: "密歇根大学社会研究所（ISR）与俄亥俄学派几乎同期独立开展领导力行为研究，得出了高度平行的结论：领导行为可以沿着「员工导向」和「生产导向」两个维度加以描述。但密歇根学派受杜威实用主义和民主参与理念的影响更深，从一开始就带有更强的价值立场——李克特不仅在描述领导行为，更在论证参与式管理（System 4）是比权威式管理（System 1）更优越的组织模式。他将管理风格从独裁型到参与型排列为四个系统，主张只有达到System 4（全员参与决策、相互信任、团队协作）的组织才能实现持续的高绩效。这一规范性主张使密歇根学派比俄亥俄学派走得更远——后者是描述性的（领导行为有两个维度），前者是规范性的（参与式管理是更好的）。System 4思想深刻影响了后来的质量圈运动和日本式参与管理实践。",
    concepts: ["k147", "k148", "k149"],
    influence: "System 4思想影响了后来的参与式管理实践和质量圈运动。与俄亥俄学派共同构成领导力行为研究的双峰，是现代领导力理论的重要源头。",
    context: "密歇根研究与俄亥俄研究几乎同期，均产生于战后美国大规模组织管理的需求背景，但密歇根团队更受杜威实用主义和民主参与理念的影响，对员工参与和民主管理持更积极的规范立场。主要局限在于：员工导向领导效果更好的结论主要来自对特定行业的横截面研究，因果关系难以确认；System 1-4模型的实践推广性受制于组织文化惯性，转型成本极高；此外，参与式管理在专业知识不对称显著的场合（如技术密集型岗位）未必优于指令型管理。",
