    group: 12,
    title: "斯坦福学派", en: "Stanford University (GSB & Sociology Dept.)", ja: "スタンフォード学派",
    era: "1970s– 制度理论与组织生态",
    who: ["约翰·W·迈耶 John W. Meyer", "布赖恩·罗恩 Brian Rowan", "迈克尔·汉南 Michael Hannan", "约翰·弗里曼 John Freeman", "詹姆斯·马奇 James March（后期在斯坦福）"],
    summary: "斯坦福的跨学科氛围（社会学、教育学、商学交叉）孕育了两条深刻挑战理性行动者模型的研究脉络。迈耶与罗恩（1977）开创的新制度主义追问：组织的正式结构为什么与实际运作如此脱节？他们的回答颠覆了效率观——正式结构不是为了提高效率而是为了获得合法性的「仪式」，这与迪马吉奥和鲍威尔的同构化理论合流，共同构成了制度理论学派的两大支柱。汉南与弗里曼的组织生态学则走向了更为激进的结构决定论——用自然选择的逻辑研究组织种群的生存与消亡，主张组织受制于结构惯性（structural inertia）无法有效适应环境变化，行业演化主要通过不适者的消亡和新组织的诞生来实现。马奇后期移至斯坦福后进一步丰富了这一批判传统。两条脉络都对管理者的战略能动性持深刻怀疑态度——这使斯坦福学派成为管理学中最具社会学批判色彩的学术阵地。",
    concepts: ["k159", "k161"],
    influence: "新制度主义与迪马吉奥-鲍威尔的同构化理论合流，成为制度理论学派的两大支柱。组织生态学开创了用生物演化逻辑分析组织种群的研究传统。",
    context: "1970年代组织社会学兴起，研究者开始系统质疑纯粹效率视角对组织行为的解释局限，斯坦福的跨学科氛围（社会学、教育学、商学交叉）为新制度主义和组织生态学的发展提供了独特土壤。两条研究脉络均对理性行动者模型提出了根本性挑战。主要局限在于：新制度主义强调外部压力对组织的制约，在解释组织创新和变革时陷入被动；组织生态学的\"选择压力\"论被批评为结构决定论，低估了管理者的战略能动性；此外，两者均更擅长描述和解释已发生的现象，对管理实践的前瞻性指导有限。",
