    summary: "人的资源管理（HRM）是20世纪后半叶管理思想的一次范式转换：从把人视为可替换的成本要素（传统人事劳务管理），转变为把人视为组织最重要的战略性资产。这一转换的理论基础由两个模型同时奠定——比尔的哈佛模型主张HRM必须平衡多方利益相关者的诉求（软性视角），冯布伦的密歇根模型强调HRM必须与企业战略保持纵向匹配（硬性视角），两者分别代表了以人为本和以战略为本的基本取向。围绕是否存在普遍有效的HRM实践（最佳实践派 vs 最佳匹配派）的理论争论至今未有定论，是该领域最持久的学术课题。",
