    influence: "将人力资源管理从行政职能提升为战略职能，推动了CHO（首席人力资源官）制度的普及；AMO框架成为当代HRM研究最主流的分析工具；高承诺工作系统思想渗透进敏捷组织、自我管理团队等现代组织设计实践中。",
    context: "1970-80年代美日企业竞争力差距引发美国学界对人力资源管理的系统性反思，传统的人事管理（Personnel Management）被批评为缺乏战略眼光、止步于行政事务。主要局限在于：战略匹配的测量和操作化至今存在挑战；最佳实践与权变匹配之间的张力难以调和；此外，SHRM理论主要以西方正式雇用关系为前提，在零工经济、灵活用工等新型劳动形态下的适用性受到质疑。",
