    summary: "斯科特四象限中最早出现的理论群落。在这一视角下组织被视为追求效率的理性机器：存在唯一最优的组织设计方案，管理者的任务是通过科学分析找到它并加以实施。「封闭」意味着忽略外部环境的影响，假定组织可以在稳定条件下独立运作；「合理」意味着组织的结构和行为都是精心设计的理性产物，而非自发形成的社会秩序。泰勒的科学管理从车间操作层面、韦伯的官僚制从社会结构层面、法约尔的管理过程从经营者层面，各自为这一象限提供了理论支柱。这三大学派共同奠定了20世纪上半叶管理思想的主导范式，其核心假设在1930年代被人际关系学派（均衡学派）首次挑战，在1960年代被系统论和权变理论（适应性设计学派）从根本上颠覆。",
