    summary: "跨国企业研究的核心理论问题是：如果在外国经营意味着面对语言、制度和文化的陌生性劣势（liability of foreignness），那么跨国扩张的经济理性何在？海默（1960）率先提出企业进行对外直接投资是因为拥有足以抵消海外劣势的垄断性优势。邓宁（1976）将这一逻辑发展为综合性的OLI范式——企业必须同时具备所有权优势、区位优势和内部化优势，三者缺一不可才会选择FDI而非出口或许可。在组织层面，戈沙尔与巴特利特（1989）通过对大型跨国公司的比较研究提出I-R矩阵框架和跨国型组织模式——这不仅是组织设计问题，更揭示了全球效率与本地适应之间不可完全消解的根本张力。",
