    context: "1960-70年代战后全球化加速，美国跨国公司的急速扩张引发了学界对企业跨国行为动因的广泛关注。海默1960年的MIT博士论文首次提出企业层面的FDI理论，邓宁于1976年发展出综合性的OLI框架，戈沙尔则在1980年代通过对大型跨国公司的比较研究提出了跨国型模式。主要局限在于：OLI框架本质上是静态的，对国际化路径的动态演化解释有限；跨国型企业模式在现实中极难实现——全球整合与本地响应之间往往存在真实的资源冲突；新兴市场企业的国际化路径（以弥补资产为动机的FDI）也难以用传统框架解释。",
