    summary: "组织的结构形态随着技术和环境的变迁经历了持续的演化。最早的直线组织和职能制适应了工业化大生产的需求；钱德勒记录了美国大企业从职能制向事业部制（M型组织）的历史转变——「结构追随战略」的命题由此诞生；矩阵制试图在职能专业化和项目灵活性之间找到平衡。伯恩斯与斯托克（1961）提出了该领域最具影响力的理论区分：机械式组织（高度标准化·层级分明·适合稳定环境）与有机式组织（灵活·扁平·适合变化环境），直接奠定了权变理论的基础。21世纪的组织形态探索走向了更加激进的方向——拉卢的青色组织（Teal Organization）主张完全的自我管理取代层级控制，合弄制（Holacracy）以角色而非职位为组织单元，但这些前沿实验的可推广性仍有待验证。",
