  // ===== 第二批新增：意思決定論 =====
  decision_theory: {
    accent: "#FF9500", badge: "マクロ · 意思決定 · 1940s–",
    group: 4,
    title: "决策组织理论", en: "Decision Theory", ja: "意思決定論",
    era: "1940s– Simon → March → Kahneman",
    who: ["赫伯特·西蒙 Herbert Simon", "詹姆斯·马奇 James March", "理查德·塞尔特 Richard Cyert", "伊戈尔·安索夫 Igor Ansoff"],
    summary: "以决策为核心分析单位来研究个人与组织行为的理论学派。核心命题是管理的本质就是决策——组织的一切活动归根结底都可以还原为一系列决策过程。人的理性是有限的，不可能达到完全最优；决策的现实形态是满意化而非最优化；组织是决策的系统，而不仅仅是命令—服从的结构。由卡内基梅隆大学的一批学者（西蒙→塞尔特→马奇→奥尔森）发展起来，统称为卡内基学派。该学派提出的有限理性概念后来为行为经济学提供了思想前提。决策论与组织学习论是一体两面的关系——两者都以有限理性为共同前提，前者关注如何做决策，后者关注如何从决策结果中学习。",
    concepts: ["k573","k574","k575","k576","k577","k578","k579","k580","k581","k582","k583","k584","k585","k586"],
    influence: "决策组织理论是组织理论的核心支柱之一。西蒙因有限理性研究获1978年诺贝尔经济学奖；卡尼曼因前景理论获2002年诺贝尔经济学奖。垃圾桶模型深刻影响了公共政策研究（Kingdon的政策流理论）和大学治理研究。",
    context: "传统经济学假设完全理性的「经济人」，但1940年代起西蒙等指出现实中人类认知能力有限，决策过程远非最优化。这一挑战催生了行为决策学派，其洞见后来汇入行为经济学（卡尼曼、特沃斯基），并对AI决策系统、医疗诊断、公共政策等领域产生广泛影响。",
    related: ["卡内基学派", "行为经济学派", "知识管理学派"]
  },

  // ===== 第二批新增：組織学習 =====
