    summary: "组织基于经验反馈，持续调整行为、信念、规则和知识的过程。组织学习不是个人学习的简单加总，而是在组织层面沉淀为制度、流程、文化的集体行为改变。学习是组织适应环境的根本机制，发生在惯例（routine）层面，既可能带来适应也可能带来僵化（能力陷阱）。位于组织行为学与战略管理的交叉领域，与知识管理、组织变革、创新管理密切相关。塞尔特与马奇（1963）首次将学习作为组织行为核心机制；阿吉里斯（1978）区分单环/双环学习揭示学习深度；马奇（1991）提出探索与利用的根本张力；圣吉（1990）将学术洞见通俗化为学习型组织；野中（1995）从知识创造角度贡献了SECI模型。",
