    influence: "组织学习理论深刻影响了知识管理（野中SECI）、动态能力理论（Teece）和创新管理（Christensen的创新者困境本质上是能力陷阱的体现）。两利手经营已成为当代战略管理的核心议题。",
    context: "1970年代后，环境变化加速使组织持续学习能力成为竞争优势的关键。阿吉里斯从行动科学角度、马奇从决策理论角度分别构建了组织学习的两大学派。1990年代圣吉将其通俗化为管理实践指南。但理论存在测量困难（如何衡量「组织已学习」）和边界模糊（与知识管理、组织变革的重叠）等问题。",
