    contribution: "厄威克是将法约尔行政管理理论系统化、国际化传播的最重要推动者。他整合了法约尔、泰勒、福莱特等人的理论，提出了管理的八项原则，并在1937年与古利克共同主编《管理科学论文集》，系统阐述了POSDCORB模型（计划、组织、人员配置、指挥、协调、报告、预算），成为公共行政和企业管理教育的经典框架。他还积极推动管理学职业化，是英国管理学会的创始人之一。"
