    contribution: "斯蒂格勒是芝加哥学派的核心成员，1982年诺贝尔经济学奖得主。他对管理学最重要的贡献是提出监管俘获理论（Regulatory Capture Theory）——政府监管机构往往被其所监管的产业所俘获，最终服务于被监管者的利益而非公众利益，为理解产业政策和竞争监管提供了深刻洞见。他还对信息经济学做出基础性贡献，1961年发表《信息经济学》，首次系统分析信息搜寻成本对市场价格分散的影响，开创了信息不对称研究的早期路径，与后来的代理理论产生深刻关联。",
