    contribution: "卡茨是密歇根大学社会研究所的重要成员，与罗伯特·卡恩共同出版了《组织的社会心理学》（1966），这是将系统理论和社会心理学方法系统应用于组织分析的奠基性著作。他们将组织界定为开放系统，分析了组织的能量输入-转换-输出过程、系统维护与适应机制，以及组织角色、规范和价值观如何构成组织的社会心理基础。这一框架成为系统管理学派和组织行为学交叉领域的重要文献，对组织理论的系统化发展做出了重要贡献。"
