    contribution: "伍德沃德是权变理论最早的实证先驱之一。她在1950年代对英国埃塞克斯地区100余家制造企业的大规模调查中，发现技术类型（而非规模或行业）是预测组织结构的关键变量：单件生产和流程生产企业结构相似（有机式），而批量生产企业结构截然不同（机械式）。这一发现推翻了古典管理理论关于最优管理幅度和层级数量的普遍主义主张，成为权变理论最重要的早期实证依据之一。她的研究直接影响了后来阿斯顿研究团队的工作以及汤普森对技术与组织依存关系的系统理论化。"
