    contribution: "奎因是战略形成学习学派的核心代表人物。他1978年发表于《斯隆管理评论》的论文《战略变革：论理的渐进主义》和1980年的著作《战略：变革的过程》通过对9家大企业高层管理者的深度访谈，提炼出「论理的渐进主义」框架，填补了理性规划模型（安索夫等）与纯粹涌现学习模型之间的空白。他的研究揭示：优秀的战略家并非遵循理性蓝图，而是通过有意管理的渐进学习过程来形成和调整战略。这一洞察至今仍是理解创新驱动型企业和政治性组织战略形成过程的重要框架。"
