  "领导与管理的区分": "リーダーシップとマネジメントの区分（Bennis）",
  "个人意思决定与集团意思决定": "個人意思決定と集団意思決定（Individual vs Group Decision Making）",
  "SECI模型与Ba（场）": "SECIモデルと場（Ba）——知識創造の四段階と場の理論",
  "日本经营体制特征": "日本的経営の制度的特徴（企業集団・メインバンク・稟議制等）",
  "比尔变革模型": "ビールの変革モデル（Beer's Change Model）",
  "未成熟-成熟理論": "未成熟—成熟理論（Immaturity-Maturity Theory，Argyris，1957）",
  "人的资源管理的定义与功能": "人的資源管理（HRM）の定義と機能",
  "人与其他经营资源的差异": "人と他の経営資源の違い",
  "人事劳务管理→人的资源管理的范式转换": "人事労務管理から人的資源管理へのパラダイム転換",
  "人间模型的变迁": "人間モデルの変遷（経済人→社会人→自己実現人→複雑人）",
  "采用管理": "採用管理（リクルートメント＆セレクション）",
  "配置与人事异动": "配置と人事異動（配置転換・出向・転籍）",
  "晋升管理与职业高原": "昇進管理とキャリア・プラトー（Career Plateau）",
  "薪酬制度": "報酬制度（年功給・職能給・職務給・成果給）",
  "人事评价偏差": "人事評価バイアス（ハロー効果・中心化傾向・寛大化傾向等）",
  "日本的雇用惯行": "日本的雇用慣行（メンバーシップ型雇用と三種の神器）",
  "劳使关系": "労使関係（団体交渉・春闘・労使協議制）",
  "国际人力资源管理": "国際人的資源管理（IHRM：PCN・HCN・TCN・EPRG）",
  "福利厚生制度": "福利厚生制度（法定福利・法定外福利・カフェテリアプラン）",
  "林格曼效应": "リンゲルマン効果・社会的手抜き（Social Loafing）",
